from __future__ import division
import math
import random

def distance(point1, point2):
    return math.sqrt((point1[0] - point2[0])**2 + (point1[1] - point2[1])**2)

def assign_clusters(points, centers):
    clusters = [[] for _ in centers]
    for point in points:
        distances = [distance(point, center) for center in centers]
        min_index = distances.index(min(distances))
        clusters[min_index].append(point)
    return clusters

def move_centers(clusters):
    centers = []
    for cluster in clusters:
        x = sum([p[0] for p in cluster]) / len(cluster)
        y = sum([p[1] for p in cluster]) / len(cluster)
        centers.append((x, y))
    return centers

def kmeans(points, k):
    centers = [(random.randint(0, 10), random.randint(0, 10)) for _ in range(k)]
    while True:
        clusters = assign_clusters(points, centers)
        new_centers = move_centers(clusters)
        if new_centers == centers:
            break
        centers = new_centers
    return centers

import java.util.Arrays;

public class WaveForm {
    public static void convertToWaveForm(int[] arr) {
        int n = arr.length;

        for (int i = 0; i < n; i += 2) {
            if (i > 0 && arr[i] < arr[i - 1])
                swap(arr, i, i - 1);

            if (i < n - 1 && arr[i] < arr[i + 1])
                swap(arr, i, i + 1);
        }
    }

    private static void swap(int[] arr, int i, int j) {
        int temp = arr[i];
        arr[i] = arr[j];
        arr[j] = temp;
    }

    public static void main(String[] args) {
        int[] arr = {2, 4, 7, 8, 9, 3};

        System.out.println("Original array:");
        System.out.println(Arrays.toString(arr));

        convertToWaveForm(arr);

        System.out.println("\nWave form array:");
        System.out.println(Arrays.toString(arr));
    }
}

