import java.text.*;

public class DiseaseSpreadSimulation {

    public static void main(String[] args) {
        // Initialize formatter for printing results
        NumberFormat formatter = new DecimalFormat("##0.00");

        // Initialize disease spread variables
        int population = 10000;
        double r0 = 2.5;
        double recoveryPeriod = 14.0;
        double avgContactRate = 3.0;

        // Calculate probability of infection
        double infectionProb = r0 / avgContactRate;

        // Initialize current and next day cases
        int currentCases = 1;
        int nextDayCases = 0;

        // Simulate for 100 days
        for(int day=1; day <= 100; day++){

            // Calculate number of new infections
            int totalSpreaders = Math.min(currentCases, population - currentCases);
            nextDayCases = (int)((double)totalSpreaders * avgContactRate * infectionProb);
            if(nextDayCases < 0)
                nextDayCases = 0;
            nextDayCases += currentCases;

            // Recover old infections
            if(day > recoveryPeriod){
                int recovering = (int)((double)currentCases * infectionProb);
                nextDayCases -= recovering;
            }

            // Update current cases
            currentCases = nextDayCases;

            // Print result
            System.out.println("After day " + day + ": "+ formatter.format((double)currentCases/population * 100.0) + "% of population infected");
        }
    }
}

