import React from 'react';
import axios from 'axios';

class FlightSearchForm extends React.Component {
  constructor(props) {
    super(props);
    this.state = {
      from: '',
      to: '',
      date: '',
      flights: []
    };
  }

  handleChange = (event) => {
    this.setState({
      [event.target.name]: event.target.value
    });
  }

  handleSubmit = (event) => {
    event.preventDefault();
    const { from, to, date } = this.state;
    axios.get(`https://www.skyscanner.net/datapoint/datesearch/v1/json/${from}/${to}/${date}`)
      .then(response => {
        this.setState({ flights: response.data });
      });
  }

  render() {
    const { from, to, date, flights } = this.state;
    return (
      <div>
        <h1>Flight Search</h1>
        <form onSubmit={this.handleSubmit}>
          <label>
            From:
            <input type="text" name="from" value={from} onChange={this.handleChange} />
          </label>
          <label>
            To:
            <input type="text" name="to" value={to} onChange={this.handleChange} />
          </label>
          <label>
            Date:
            <input type="date" name="date" value={date} onChange={this.handleChange} />
          </label>
          <button type="submit">Search</button>
        </form>
        <h2>Flights</h2>
        <ul>
          {flights && flights.length > 0 ? (
            flights.map(flight => (
              <li key={flight.id}>{flight.name}</li>
            ))
          ) : (
            <p>No flights found.</p>
          )}
        </ul>
      </div>
    );
  }
}

export default FlightSearchForm;

