from abc import ABC, abstractmethod
import math


class Car(ABC):
    def __init__(self, make: str, model: str, engine: bool):
        self.make = make
        self.model = model
        self.engine = engine

    @abstractmethod
    def get_price(self):
        pass

    @property
    def tax_rate(self):
        return 1.08


class ElectricCar(Car):
    def __init__(self, make: str, model: str, engine: bool):
        super().__init__(make, model, engine)

    def get_price(self, battery_capacity: int, range: int):
        return 20000 + battery_capacity * 100 - range * 100

    @classmethod
    def from_string(cls, string: str):
        make = string[0]
        model = string[1]
        engine = string[2:]
        return cls(make, model, engine)


class PetrolCar(Car):
    def __init__(self, make: str, model: str, engine: bool):
        super().__init__(make, model, engine)

    def get_price(self, cc: int, hp: int):
        return 15000 + cc / 1000 - hp * 10

    def get_price_with_tax(self, cc: int, hp: int):
        return self.get_price(cc, hp) * self.tax_rate

    @staticmethod
    def calculate_take_off_speed(cars):

        c0 = 10
        c1 = 0.5
        c2 = 0.3

        for car in cars:
            weight = 1500
            hp = 100
            friction = 0.1
            take_off_speed = c0 * hp ** 0.5 + c1 * math.log(weight) + c2 * friction ** 2
            return take_off_speed

